'use strict';
const $ = s => document.querySelector(s);
const money = n => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:0}).format(n);
const escapeHTML = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H14v-7h-4v7H3z"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>',trips:'<path d="m3 5 1 1 2-2M9 5h12M3 12l1 1 2-2M9 12h12M3 19l1 1 2-2M9 19h12"/>',learn:'<path d="M8 8H5a3 3 0 1 1 3-3v14a3 3 0 1 1-3-3h14a3 3 0 1 1-3 3V5a3 3 0 1 1 3 3H8"/>',profile:'<circle cx="12" cy="7" r="3.5"/><path d="M5 21v-3a7 7 0 0 1 14 0v3z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>',tide:'<path d="M3 5c4 4 8-4 18 0M3 12c4 4 8-4 18 0M3 19c4 4 8-4 18 0"/>',temp:'<path d="M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0Z"/><path d="M12 7v10"/>',shield:'<path d="m12 3 8 3v6c0 6-8 9-8 9s-8-3-8-9V6z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3z"/><circle cx="12" cy="13" r="4"/>',fish:'<path d="M4 12s5-8 12-4l5-4v16l-5-4C9 20 4 12 4 12Z"/><circle cx="9" cy="11" r=".5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',seat:'<path d="M6 3h12v10H6zM4 13h16v5H4zM6 18v3M18 18v3"/>',back:'<path d="m15 5-7 7 7 7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.tide}</svg>`;
const photo='assets/moalboal.png';
const turtle='assets/turtle.png';
const homePhoto='assets/moalboal-home.png';
const trips={morning:{id:'morning',site:'Bulak Point',title:'Bulak Point · Morning Dive',operator:'Tindahan ni Nicky',date:'17 Oct 2026',time:'8:00 AM',duration:'3 hours',type:'2 guided reef dives',condition:'20m visibility · 28°C · calm',requirement:'Open Water certified',seats:8,booked:2,price:2400,meeting:'Panagsama Beach, Moalboal',included:'Boat, dive guide, tanks, weights and marine fees',photo},afternoon:{id:'afternoon',site:'Bulak Point',title:'Bulak Point · Afternoon Dive',operator:'Tindahan ni Nicky',date:'17 Oct 2026',time:'1:00 PM',duration:'3 hours',type:'2 guided reef dives',condition:'20m visibility · 28°C · calm',requirement:'Open Water certified',seats:8,booked:4,price:2400,meeting:'Panagsama Beach, Moalboal',included:'Boat, dive guide, tanks, weights and marine fees',photo}};
const screens=[
 ['intro','Education section','Getting started'],['login','Login','Getting started'],['register','Register · Name','Getting started'],['account','Register · Account','Getting started'],['operator','Register as operator','Getting started'],
 ['home','Home dashboard','Discovery'],['filter','Filter your dive','Discovery',true],['rank','Ranked recommendations','Discovery',true],['map','Dive communities · Map','Discovery'],['site','Moalboal · Operators','Discovery'],['conditions','Marine conditions','Discovery'],
 ['trip','Recommended trip','Seamless transaction',true],['open','Open trip · Seats','Seamless transaction',true],['summary','Booking summary','Seamless transaction',true],['payment','Payment','Seamless transaction',true],['confirmation','Confirmation','Seamless transaction',true],['mytrips','My Trips','Seamless transaction',true],
 ['identify','Marine identification','Explore & learn'],['learn','Learn','Explore & learn'],['profile','Diver profile','Explore & learn']
];
const notes={intro:['DIVINA’s product promise','A dive companion that connects discovery, suitable recommendations, and trips you can join.'],home:['A recommendation you can book','The recommendation card includes a real departure, an operator, price, available seats, and a direct link to the trip.'],filter:['Filter → Rank → Recommend','Preferences carry through to a suitable trip. Explore the illustrative recommendations in this demo.'],rank:['A suitable match','Ranking considers experience, dive type, conditions, location, and your chosen date. The top result connects to an available trip.'],trip:['6 seats available','Every detail needed to decide is visible before joining. Use “JOIN TRIP” for the morning departure or explore the open afternoon trip.'],open:['Join solo or as a small group','Eight seats, four already booked. Choose one to four divers and join the afternoon departure without organising a full boat.'],summary:['Clear cost before payment','Change the number of divers. The total updates immediately, and the cancellation policy is visible before checkout.'],payment:['Simple payment step','Choose GCash, Maya, or a card. “PAY & CONFIRM” simulates a payment; it never charges or asks for payment credentials.'],confirmation:['A completed booking','The confirmation includes the selected departure, number of divers, meeting point, booking reference, and total paid.'],mytrips:['Bookings stay accessible','Bookings created in this browser are saved locally and appear alongside example completed and cancelled trips.']};
const stages=['Filter','Rank','Recommend','View trip','Join / Book','Pay','Confirm'];
const phase={intro:0,login:0,register:0,account:0,operator:0,home:2,filter:0,rank:1,map:2,site:2,conditions:2,trip:3,open:4,summary:4,payment:5,confirmation:6,mytrips:6,identify:2,learn:2,profile:2};
let bookings=[];try{bookings=JSON.parse(localStorage.getItem('divina-bookings-v1')||'[]');if(!Array.isArray(bookings))bookings=[];}catch{}
let state={screen:'home',trip:'morning',divers:1,method:'GCash',booking:null,tab:'UPCOMING',certification:'Open Water',type:'Reef diving',date:'2026-10-17',name:'John',learning:null,availableOnly:true};
const getTrip=()=>trips[state.trip];
const seatsLeft=t=>Math.max(0,t.seats-t.booked-bookings.filter(b=>b.tripId===t.id&&b.status==='UPCOMING').reduce((n,b)=>n+b.divers,0));
const logo=(large=false)=>`<div class="logo${large?' large':''}"><img class="brand-logo" src="assets/divina-logo.png" alt="DIVINA"></div>`;
const btn=(text,action,cls='',attrs='')=>`<button class="pill ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const row=(label,value)=>`<div class="row"><span>${label}</span><strong>${value}</strong></div>`;
const badge=(text,cls='')=>`<div class="badge ${cls}">${text}</div>`;
const img=(src=photo,cls='trip-photo',alt='Diver beneath a school of fish at Moalboal')=>`<img class="${cls}" src="${src}" alt="${alt}">`;
const heading=(title,back='home',step='')=>`<div class="back-heading"><button data-go="${back}" aria-label="Back">${icon('back')}</button><h2>${title}</h2></div>${step?`<div class="step-line">${step}</div>`:''}`;
const countSelector=()=>`<div class="counter"><button data-action="minus" aria-label="Remove a diver" ${state.divers<=1?'disabled':''}>−</button><b>${state.divers} ${state.divers===1?'diver':'divers'}</b><button data-action="plus" aria-label="Add a diver" ${state.divers>=seatsLeft(getTrip())?'disabled':''}>+</button></div>`;
const seatIndicator=t=>`<div class="seats" aria-label="${t.booked+bookings.filter(b=>b.tripId===t.id&&b.status==='UPCOMING').reduce((n,b)=>n+b.divers,0)} booked, ${seatsLeft(t)} available">${Array.from({length:t.seats},(_,i)=>`<span class="seat ${i<t.seats-seatsLeft(t)?'booked':i<t.seats-seatsLeft(t)+state.divers?'selected':''}" aria-hidden="true">${icon('seat')}</span>`).join('')}</div><div class="micro muted">Blue: booked · Light blue: your group · Green: available</div>`;
function formField(label,name,placeholder,type='text',value=''){return `<label class="field">${label}<input name="${name}" type="${type}" placeholder="${placeholder}" ${value?`value="${escapeHTML(value)}"`:''} required></label>`;}
function policy(){return `<div class="card"><h4>Cancellation / booking policy</h4><p class="small muted">Free cancellation up to 24 hours before departure. Within 24 hours: non-refundable. Operator cancellations: full refund or reschedule.</p><p class="small muted">Your seat is confirmed after payment.</p></div>`;}
function summaryCard(t){return `<div class="card">${img(t.photo)}<h3>${t.title}</h3><p class="small">${t.operator}</p>${row('Date / time',t.date+' · '+t.time)}${row('Meeting point',t.meeting)}${badge(seatsLeft(t)+' seats available · Join an existing trip')}</div>`;}
function footer(label,action){return `<div class="booking-footer">${row('Total',money(getTrip().price*state.divers))}${btn(label,action)}</div>`;}
function view(screen){const t=getTrip(),left=seatsLeft(t);switch(screen){
case 'intro':return `<div class="screen"><div class="marine-hero">${logo()}<div class="tagline">Smart dive companion</div><h3 style="margin-top:25px">Dive with confidence.</h3><p class="intro-copy">Find the right dive. Find a trip you can join. Book it in one seamless flow.</p></div><div class="card"><h3>Your dive, thoughtfully connected.</h3><p class="intro-copy muted">Explore dive sites and marine conditions. Find a dive that suits your experience, then join a departure with available seats.</p><div class="flow-chips"><span>FILTER</span><span>RANK</span><span>RECOMMEND</span><span>VIEW TRIP</span><span>JOIN</span><span>PAY</span><span>CONFIRM</span></div></div><div class="card"><h4>Before you dive</h4><p class="small muted">Check your certification, review local conditions, and follow your dive operator’s briefing. DIVINA helps you find and coordinate a suitable trip.</p></div>${btn('CONTINUE','go:login')}</div>`;
case 'login':return `<form class="screen auth-screen" data-form="login"><div class="card auth-card"><div class="auth-logo"><p>Welcome back to</p>${logo(true)}</div>${formField('Email','email','johndoe@email.com','email')}${formField('Password','password','Your password','password')}<button type="button" class="text-button" data-action="forgot" style="text-align:right">Forgot password?</button><button class="pill" type="submit">Login</button>${btn('Register','go:register','secondary')}<p class="micro muted">Demo sign-in. Use any email and password.</p></div></form>`;
case 'register':return `<form class="screen auth-screen" data-form="name"><div class="card auth-card"><div class="auth-logo"><p>Register on</p>${logo(true)}</div>${formField('First name','firstName','John')}${formField('Last name','lastName','Doe')}<button class="pill" type="submit">Next</button>${btn('Register as diving operator','go:operator','secondary')}</div></form>`;
case 'account':return `<form class="screen auth-screen" data-form="account"><div class="card auth-card"><div class="auth-logo">${logo(true)}</div>${formField('Email','email','johndoe@email.com','email')}${formField('Password','password','Create a password','password')}<label class="field">Certification<select name="certification"><option>Open Water</option><option>Advanced Open Water</option><option>Rescue Diver</option></select></label><button class="pill" type="submit">Create account</button><p class="micro muted">This demo does not create an account or store your password.</p></div></form>`;
case 'operator':return `<form class="screen auth-screen" data-form="operator"><div class="card auth-card"><div class="auth-logo"><p>Register as operator</p>${logo(true)}</div>${formField('Operator / shop name','operator','Dive shop name')}${formField('Contact email','email','operator@email.com','email')}${formField('Meeting / departure location','meeting','Panagsama Beach, Moalboal')}<button class="pill" type="submit">Register operator</button>${btn('Back to diver registration','go:register','secondary')}<p class="micro muted">Demonstration form. No operator account is created.</p></div></form>`;
case 'home':return `<div class="screen"><div class="marine-hero">${logo()}<div class="tagline">Smart dive companion</div><div class="small" style="margin-top:26px">Current Marine Conditions:</div><div class="conditions"><div class="condition">${icon('eye')}<div>Visibility<br><b>10m – 20m</b></div></div><div class="condition">${icon('tide')}<div>Tide<br><b>1.5m</b></div></div><div class="condition">${icon('temp')}<div>Temperature<br><b>28°C</b></div></div><div class="condition">${icon('shield')}<div>Diving Status<br><b>Safe</b></div></div></div><button class="text-button booked-area full" data-go="conditions"><span>Booked area:<br><b>Malapascua</b></span>${icon('arrow')}</button></div><h2>Recommended for you</h2><div class="card recommend-card">${img(homePhoto)}<div class="rec-copy"><h3>Bulak Point</h3><p class="micro muted">Suitable match · Moalboal, Cebu</p><p class="micro muted">Tindahan ni Nicky · 17 Oct, 8:00 AM</p>${badge(seatsLeft(trips.morning)+' SEATS AVAILABLE')}<b>${money(2400)} / diver</b>${btn('VIEW TRIP','select:morning','compact')}</div></div><p class="promise">Find the right dive. Find a trip you can join. Book it in one seamless flow.</p>${btn('FIND MY NEXT DIVE','go:filter','secondary compact')}<div class="flow-chips"><span>Filter</span><span>Rank</span><span>Recommend</span><span>Book</span></div></div>`;
case 'filter':return `<form class="screen" data-form="filter">${heading('Find your dive')}<p class="small muted">Choose a dive that fits you. We’ll connect your match to trips you can join.</p><div class="card"><h3>Your dive preferences</h3><label class="field">Area<select name="area"><option>Moalboal, Cebu</option></select></label>${formField('Date','date','','date',state.date)}<label class="field">Experience requirement<select name="certification"><option>Open Water</option><option>Advanced Open Water</option><option>Rescue Diver</option></select></label><label class="field">Dive type<select name="type"><option>Reef diving</option><option>Marine life photography</option></select></label><label class="check-option"><input type="checkbox" name="available" ${state.availableOnly?'checked':''}>Show trips with available seats</label></div><div class="card"><h4>Your comfort matters</h4><p class="small muted">Matches consider certification and current site conditions. Your operator confirms the final dive plan.</p></div>${btn('FIND SUITABLE DIVES','submit-filter')}<p class="micro muted">Illustrative trip availability for the prototype.</p></form>`;
case 'rank':return `<div class="screen">${heading('Recommended for you','filter')}<p class="small muted">Ranked for ${escapeHTML(state.certification)} · ${escapeHTML(state.type)} · ${new Date(state.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</p><div class="card"><div class="rank-item"><div class="rank-number">01</div>${img()}<div class="rank-copy"><h3>Bulak Point</h3><p class="muted">Moalboal · Calm reef dive</p>${badge('SUITABLE MATCH')}</div></div><p class="small muted">Open Water friendly, calm site conditions, and guided reef dives.</p>${badge(seatsLeft(trips.morning)+' SEATS AVAILABLE')}<p class="small">${money(2400)} / diver · ${state.date==='2026-10-17'?'Your selected date':'Next available: 17 Oct 2026'}</p>${btn('VIEW AVAILABLE TRIP','select:morning')}</div>${!state.availableOnly?`<div class="card"><div class="rank-item"><div class="rank-number">02</div>${img(turtle,'trip-photo','Sea turtle at Moalboal')}<div class="rank-copy"><h3>Pescador Island</h3><p class="muted">Reef and marine life</p></div></div><p class="small muted">No departure listed for your date.</p>${btn('EXPLORE SITE','go:site','secondary compact')}</div>`:''}<p class="promise">Your recommendation connects directly to an operator’s bookable departure.</p></div>`;
case 'map':return `<div class="screen map-screen"><div class="map-surface"><img src="assets/map.png" alt="Map of Cebu City and nearby dive communities"></div><div class="map-overlay"><label class="search-bar"><input id="map-search" placeholder="Search diving communities and sites…" aria-label="Search dive sites">${icon('search')}</label><button class="map-pin" data-go="site" aria-label="Explore Moalboal">${icon('fish')}</button><span class="map-label">Moalboal</span><div style="margin-top:auto;margin-bottom:20px">${btn('EXPLORE MOALBOAL','go:site')}</div></div></div>`;
case 'site':return `<div class="screen map-screen"><div class="map-surface"><img src="assets/map.png" alt="Map of Cebu"></div><div class="map-overlay" style="flex:0"><label class="search-bar"><input placeholder="Search diving communities and sites…" aria-label="Search communities">${icon('search')}</label></div><div class="map-sheet"><div class="sheet-handle"></div><div class="counter"><h3>Moalboal</h3><button data-action="directions" aria-label="Meeting point directions">${icon('arrow')}</button></div><div class="site-gallery">${img(homePhoto)}${img(turtle,'','Sea turtle at Moalboal')}</div><p class="notice">Discover reef dives and marine life around Moalboal. Review the conditions and join a departure led by a local operator.</p><h3>Operators and shops</h3><button class="shop" data-action="select:morning">Tindahan ni Nicky <span>View trips →</span></button><button class="shop" data-action="shop">Maria’s Shop <span>Shop</span></button><button class="shop" data-action="shop">JP’s Diving School <span>School</span></button><button class="shop" data-action="shop">JM’s Snorkeling Equipments <span>Equipment</span></button>${btn('CHECK MARINE CONDITIONS','go:conditions','soft compact')}</div></div>`;
case 'conditions':return `<div class="screen" style="padding-top:35px"><div class="weather-panel"><div class="sheet-handle"></div><h3>Weather</h3><div class="card flat"><div class="weather-now"><div>Now<br><b>29° ⛅</b></div><span class="small muted">Moalboal, Cebu</span></div><div class="hourly">${['2PM','3PM','4PM','5PM','6PM','7PM'].map((h,i)=>`<span>${[29,28,28,29,30,31][i]}°<span class="sun">⛅</span>${h}</span>`).join('')}</div></div><div class="wave-panel"><span>≋ &nbsp; Wind speed</span><b>13.4kph NE</b></div><h3>Tide</h3><div class="tide-graph"><svg viewBox="0 0 340 80" aria-label="Illustrative tide curve"><path d="M0 65C35 35 55 16 85 21S150 74 190 58 250 0 285 13 320 21 340 26"/></svg><div class="legend"><span>7:02AM</span><span>1:26PM</span><span>11:16PM</span></div></div><div class="wave-panel"><span>≋ &nbsp; Water current</span><b>Calm</b></div><div class="form-grid"><div class="card flat"><span>Water temperature</span><h3>29°</h3></div><div class="card flat"><span>Visibility</span><h3>20m</h3></div></div><p class="micro muted">Example conditions shown in the working prototype.</p>${btn('VIEW BULAK POINT TRIP','select:morning')}</div></div>`;
case 'trip':return `<div class="screen">${heading('Recommended Trip',state.booking?'confirmation':'rank')}<div class="step-line">Suitable match → Available trip</div><div class="card"><h3>${t.title}</h3><p class="small muted">${t.operator} · Moalboal, Cebu</p>${img(t.photo)}${badge(left+' SEATS AVAILABLE')}<div class="facts">${row('Dive site',t.site+', Moalboal')}${row('Date',t.date)}${row('Departure time',t.time)}${row('Duration',t.duration)}${row('Dive type',t.type)}${row('Site conditions',t.condition)}${row('Requirement',t.requirement)}${row('Meeting point',t.meeting)}</div><h4>What’s included</h4><p class="small muted">${t.included}</p><b>${money(t.price)} / diver</b><p class="micro muted">${t.seats} seats total · ${t.seats-left} booked · ${left} available</p>${btn(left?'JOIN TRIP':'TRIP FULL','join','',left?'':'disabled')}<button class="text-button" data-action="select-open">View other departures →</button></div></div>`;
case 'open':return `<div class="screen">${heading('Open Trip','trip')}<div class="card"><h3>DIVE TRIP</h3><h3>${t.title}</h3><p class="small muted">${t.operator} · Moalboal, Cebu</p><p class="small">${t.date} · ${t.time} · ${t.duration}</p>${img(t.photo)}${badge(left+' SPOTS LEFT')}<div class="counter"><span class="small">8 seats total</span><b class="small">${t.seats-left} booked · ${left} available</b></div>${seatIndicator(t)}<b>${money(t.price)} / diver</b><p class="small muted">Join solo or bring a small group. No need to fill the boat.</p><h4>Number of divers</h4>${countSelector()}<p class="small">Your group: ${money(t.price*state.divers)}</p>${btn(left?'JOIN THIS TRIP':'TRIP FULL','join','',left?'':'disabled')}<button class="text-button" data-action="select:morning">Back to recommended trip</button></div></div>`;
case 'summary':return `<div class="screen">${heading('Booking Summary',state.trip==='afternoon'?'open':'trip','1  Booking   →   2  Payment   →   3  Confirm')}${summaryCard(t)}<div class="card"><h4>Number of divers</h4>${countSelector()}${row('Price per diver',money(t.price))}${row('Total amount',money(t.price*state.divers))}</div>${policy()}${footer('CONTINUE TO PAYMENT','continue-payment')}</div>`;
case 'payment':return `<div class="screen">${heading('Payment','summary','1  Booking   →   2  Payment   →   3  Confirm')}<div class="card"><h4>BOOKING SUMMARY</h4><h3>${t.title}</h3><p class="small muted">${t.operator} · ${t.date}, ${t.time}</p>${row('Number of divers',state.divers)}${row('Subtotal',money(t.price*state.divers))}${row('Fees',money(0)+' · Included in trip price')}<hr style="border:0;border-top:1px solid #edf0f4;width:100%;margin:2px 0">${row('TOTAL','<b>'+money(t.price*state.divers)+'</b>')}</div><div class="card"><h4>Payment method</h4>${['GCash','Maya','Credit / debit card'].map((m,i)=>`<label class="method ${state.method===m?'selected':''}"><input type="radio" name="paymentMethod" value="${m}" ${state.method===m?'checked':''}>${m}<span class="method-logo" aria-hidden="true">${['G','m','▰'][i]}</span></label>`).join('')}<p class="small muted">Continue securely with your selected provider. No payment details are stored in DIVINA.</p></div><div class="card"><h4>Know what you are paying for</h4><p class="small muted">${state.divers} ${state.divers===1?'seat':'seats'} · 2 guided dives · All listed inclusions. You will receive a booking reference after payment.</p><p class="small muted">By confirming, you accept the booking policy shown in your summary.</p></div><p class="micro muted">Demo payment · no money is charged.</p>${footer('PAY & CONFIRM','pay')}</div>`;
case 'confirmation':{const b=state.booking;return `<div class="screen">${heading('Booking Confirmation','payment','Booking → Payment → Confirmed')}${!b?`<div class="card empty"><h3>No booking confirmed yet</h3><p>Join a trip and complete the demo payment to see your confirmation.</p>${btn('FIND A TRIP','select:morning')}</div>`:`<div class="card"><div class="checkout-success"><div class="success-icon">✓</div><h3>YOUR DIVE IS CONFIRMED.</h3><p class="small muted">You have a place on the trip.</p></div>${img(b.photo)}<h3>${b.title}</h3>${row('Dive site',b.site)}${row('Operator',b.operator)}${row('Date',b.date)}${row('Time',b.time)}${row('Number of divers',b.divers)}${row('Meeting point',b.meeting)}${row('Booking reference',b.reference)}${row('Amount paid',money(b.total))}${row('Payment method',b.method)}</div><p class="small muted">Arrive 15 minutes before departure. Bring your certification and booking reference.</p>${btn('VIEW TRIP DETAILS','view-confirmed')}${btn('ADD TO MY TRIPS','add-mytrips','secondary')}<p class="micro muted">Your confirmed booking is saved in My Trips.</p>`}</div>`;}
case 'mytrips':{const examples=[{...trips.morning,title:'Pescador Island',site:'Pescador Island',date:'3 Oct 2026',time:'8:30 AM',divers:2,reference:'DV-261003-002',status:'COMPLETED'},{...trips.afternoon,title:'Olango Island',site:'Olango Island',operator:'Island Dive Operator',date:'28 Sep 2026',time:'8:00 AM',divers:1,reference:'DV-260928-003',status:'CANCELLED'}];const list=[...bookings,...examples].filter(b=>b.status===state.tab);return `<div class="screen"><h2>My Trips</h2><p class="small muted">Your confirmed bookings, all in one place</p><div class="status-tabs" role="tablist" aria-label="Trip status">${['UPCOMING','COMPLETED','CANCELLED'].map(s=>`<button role="tab" aria-selected="${s===state.tab}" class="${s===state.tab?'active':''}" data-action="tab:${s}">${s}</button>`).join('')}</div>${list.length?list.map(b=>`<div class="card">${badge(b.status,b.status==='UPCOMING'?'':b.status==='CANCELLED'?'cancelled':'neutral')}<div class="trip-head">${img(b.photo)}<div><h3>${escapeHTML(b.title)}</h3><p>${b.date} · ${b.time}</p><p class="muted">${escapeHTML(b.operator)}</p></div></div><div class="trip-meta"><span>${b.divers} ${b.divers===1?'diver':'divers'}</span><span>${b.reference}</span></div>${b.status==='UPCOMING'?`<button class="confirm-detail-link" data-action="booking:${b.reference}">VIEW TRIP DETAILS →</button>`:''}</div>`).join(''):`<div class="card empty">${icon('trips')}<h3>No upcoming dives yet</h3><p class="small">Your confirmed trip will appear here after payment.</p>${btn('FIND A TRIP','select:morning')}</div>`}<p class="micro muted">Completed and cancelled cards are example bookings.</p></div>`;}
case 'identify':return `<div class="screen"><div class="marine-hero">${logo()}<div class="tagline">Smart dive companion</div><div class="upload-buttons"><label>${icon('upload')}Upload<input type="file" id="identify-upload" accept="image/*" hidden></label><label>${icon('camera')}Camera<input type="file" id="identify-camera" accept="image/*" capture="environment" hidden></label></div><p class="small muted" style="text-align:center">Take a photo or upload one<br>for instant identification</p><p class="micro muted" style="margin-top:12px;text-align:center">note: camera taken pictures will be the only one legible for points</p><div class="notice" style="margin-top:14px">♧ Works offline<br><span class="micro">TensorFlow Lite enables species ID without internet connection</span></div></div><div class="card"><h3>Recent Identifications</h3><div class="identify-row">${img('assets/clownfish.png','','Clownfish')}<div><h4>Clownfish (Amphiprion)</h4><p>Identified at Malapascua</p></div></div><div class="identify-row">${img('assets/blue-tang.png','','Blue Tang')}<div><h4>Blue Tang (Paracanthurus hepatus)</h4><p>Identified at Malapascua</p></div></div></div><p class="micro muted">Reference feature preview. Species identification is not connected in this web demo.</p></div>`;
case 'learn':return `<div class="screen"><div class="logo" style="justify-content:center;margin-bottom:10px"><span class="wave">≋</span><span style="color:black;font-size:21px">LEARN</span></div><label class="search-bar"><input placeholder="Search diving communities and sites…" aria-label="Search learning modules">${icon('search')}</label><h3>For divers</h3>${learningCard('Dive Smart','Safety Basics',['Pre-dive buddy check','Equipment inspection basics','Hand signals','Emergency ascent awareness'])}${learningCard('Responsible Diving','Sustainable Practices',['Buoyancy control near reefs','No anchor damage zones','Ethical underwater photography','Avoid chasing wildlife'])}<h3>Marine Species Explorer</h3>${learningCard('Introduction to Marine Life','Safety Basics',['Marine diversity','Marine animals and species','Habitats','Life underwater'])}</div>`;
case 'profile':return `<div class="screen"><h2>Diver Profile</h2><div class="card"><div class="round-placeholder">${icon('profile')}</div><h3>${escapeHTML(state.name)}’s dive profile</h3>${row('Certification',escapeHTML(state.certification))}${row('Preferred dive',escapeHTML(state.type))}</div>${btn('MY TRIPS','go:mytrips')}${btn('MARINE IDENTIFICATION','go:identify','secondary')}${btn('LEARN','go:learn','secondary')}${btn('SIGN OUT','go:login','secondary compact')}<p class="micro muted">Demo profile. Bookings are stored only in this browser.</p></div>`;
default:return '';}}
function learningCard(title,subtitle,items){return `<div class="card learning-card"><div class="learning-heading"><div class="round-placeholder"></div><div><h3>${title}</h3><p class="small">${subtitle}</p></div></div><ul>${items.map(s=>`<li>${s}</li>`).join('')}</ul>${btn('Start module','module:'+title,'compact')}${state.learning===title?`<div class="notice">Module selected. Review these topics with your certified instructor before your next dive.</div>`:''}</div>`;}
function render(){let s=screens.find(x=>x[0]===state.screen)||screens[5];state.screen=s[0];$('#app').innerHTML=view(state.screen);if(state.screen==='filter'){document.querySelector('[name=certification]').value=state.certification;document.querySelector('[name=type]').value=state.type;}$('#bottom-nav').innerHTML=['home','map','mytrips','learn','profile'].map((n,i)=>`<button data-go="${n}" title="${['Home','Dive communities','My Trips','Learn','Profile'][i]}" aria-label="${['Home','Dive communities','My Trips','Learn','Profile'][i]}" class="${(n===state.screen||(n==='home'&&['filter','rank','conditions','trip','open','summary','payment','confirmation'].includes(state.screen))||(n==='map'&&state.screen==='site')||(n==='learn'&&state.screen==='identify'))?'active':''}">${icon(['home','map','trips','learn','profile'][i])}</button>`).join('');$('#bottom-nav').hidden=['intro','login','register','account','operator'].includes(state.screen);$('#bottom-nav').style.display=$('#bottom-nav').hidden?'none':'flex';const i=screens.indexOf(s);$('#screen-select').value=state.screen;$('#screen-number').textContent=`${String(i+1).padStart(2,'0')} / ${screens.length} screens`;$('#previous').disabled=i===0;$('#next').disabled=i===screens.length-1;document.querySelectorAll('.screen-link').forEach(n=>{n.classList.toggle('active',n.dataset.go===state.screen);if(n.dataset.go===state.screen)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});const p=phase[state.screen]??2;$('#journey').innerHTML=stages.map((n,i)=>`<li class="${i===p?'current':i<p?'done':''}"><span class="step-dot">${i<p?'✓':i+1}</span><span>${n}</span></li>`).join('');$('#business-path').innerHTML=`<div class="business-path">${['SUITABLE MATCH','AVAILABLE TRIP','COMPLETED BOOKING','DIVINA TRANSACTION REVENUE'].map((n,i)=>`<span class="${(i===0&&p<3)||(i===1&&p>=3&&p<6)||(i>=2&&state.booking&&p===6)?'highlight':''}">${n}</span>`).join('')}</div>`;const note=notes[state.screen]||['Working prototype reference','Browse this existing DIVINA feature, then continue through the connected transaction flow.'];$('#note-title').textContent=note[0];$('#note-copy').textContent=note[1];document.title=`DIVINA · ${s[1]}`;}
function go(screen,replace=false){if(!screens.some(s=>s[0]===screen))screen='home';if(screen==='open'&&state.trip!=='afternoon'){state.trip='afternoon';state.divers=1;state.booking=null;}state.screen=screen;if(replace)history.replaceState(null,'','#'+screen);else if(location.hash!=='#'+screen)history.pushState(null,'','#'+screen);render();$('#app').scrollTop=0;}
function selectTrip(id,screen='trip'){state.trip=id;state.divers=1;state.booking=null;go(screen);}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function action(a){const [command,...tail]=a.split(':'),arg=tail.join(':');if(command==='go')return go(arg);if(command==='select')return selectTrip(arg);if(command==='select-open')return selectTrip('afternoon','open');if(command==='minus'||command==='plus'){const pos=$('#app').scrollTop;state.divers=Math.max(1,Math.min(seatsLeft(getTrip()),state.divers+(command==='plus'?1:-1)));render();$('#app').scrollTop=pos;return;}if(command==='join'){if(seatsLeft(getTrip())<state.divers)return toast('This departure does not have enough seats.');return go('summary');}if(command==='continue-payment'){if(state.divers>seatsLeft(getTrip()))return toast('Please choose a group size within the available seats.');return go('payment');}if(command==='pay'){if(state.divers>seatsLeft(getTrip()))return toast('This departure no longer has enough seats.');const reference='DV-261017-'+String(bookings.length+1).padStart(3,'0');state.booking={...getTrip(),tripId:state.trip,divers:state.divers,total:getTrip().price*state.divers,reference,method:state.method,status:'UPCOMING'};bookings.unshift(state.booking);try{localStorage.setItem('divina-bookings-v1',JSON.stringify(bookings));}catch{toast('Confirmed for this session. Browser storage is unavailable.');}go('confirmation');return;}if(command==='view-confirmed'){state.trip=state.booking.tripId;return go('trip');}if(command==='add-mytrips'){state.tab='UPCOMING';go('mytrips');toast('Your confirmed booking is in My Trips.');return;}if(command==='tab'){state.tab=arg;return render();}if(command==='booking'){const b=bookings.find(b=>b.reference===arg);if(b){state.booking=b;state.trip=b.tripId;state.divers=b.divers;go('confirmation');}return;}if(command==='submit-filter')return $('#app form').requestSubmit();if(command==='forgot')return toast('Demo: password recovery is not connected.');if(command==='directions')return toast('Meeting point: Panagsama Beach, Moalboal. Arrive 15 minutes early.');if(command==='shop')return toast('Shop preview. Choose Tindahan ni Nicky to see an available trip.');if(command==='module'){state.learning=arg;const pos=$('#app').scrollTop;render();$('#app').scrollTop=pos;return;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-action]');if(!b||b.disabled)return;if(b.dataset.go)go(b.dataset.go);else action(b.dataset.action);});
document.addEventListener('change',e=>{if(e.target.name==='paymentMethod'){state.method=e.target.value;const pos=$('#app').scrollTop;render();$('#app').scrollTop=pos;}if(['identify-upload','identify-camera'].includes(e.target.id)&&e.target.files?.length)toast('Photo selected. Identification is a reference feature in this demo.');});
document.addEventListener('submit',e=>{if(!e.target.dataset.form)return;e.preventDefault();const data=new FormData(e.target);switch(e.target.dataset.form){case 'login':case 'account':if(data.get('certification'))state.certification=data.get('certification');go('home');break;case 'name':state.name=data.get('firstName');go('account');break;case 'operator':go('home');toast('Operator registration demonstrated. No account was created.');break;case 'filter':state.certification=data.get('certification');state.type=data.get('type');state.date=data.get('date');state.availableOnly=data.get('available')==='on';go('rank');break;}});
$('#screen-select').addEventListener('change',e=>{if(e.target.value==='open')selectTrip('afternoon','open');else go(e.target.value);});$('#previous').onclick=()=>go(screens[Math.max(0,screens.findIndex(s=>s[0]===state.screen)-1)][0]);$('#next').onclick=()=>{const s=screens[Math.min(screens.length-1,screens.findIndex(s=>s[0]===state.screen)+1)][0];if(s==='open')selectTrip('afternoon','open');else go(s);};$('#reset').onclick=()=>{bookings=[];try{localStorage.removeItem('divina-bookings-v1');}catch{}state={...state,trip:'morning',divers:1,method:'GCash',booking:null,tab:'UPCOMING'};go('home');toast('Demo reset. You have 6 seats available on the morning trip.');};window.addEventListener('popstate',()=>go(location.hash.slice(1),true));window.addEventListener('hashchange',()=>go(location.hash.slice(1),true));
let lastGroup='';$('#screen-list').innerHTML=screens.map((s,i)=>{const group=s[2]!==lastGroup?`<div class="group-label">${s[2]}</div>`:'';lastGroup=s[2];return group+`<button class="screen-link" data-go="${s[0]}"><span class="index">${String(i+1).padStart(2,'0')}</span>${s[1]}${s[3]?'<span class="new-mark">FLOW</span>':''}</button>`;}).join('');$('#screen-select').innerHTML=screens.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('');
if(bookings.length)state.booking=bookings[0];go(location.hash.slice(1)||'home',true);
